    constructor(C _c) { c = _c; }
    function run() public payable {
        require(address(c).code.length > 0);
        c.sudicideAnyone();
        assert(address(c).code.length == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // first destruction by the owner (msg.sender of calls on c is this contract)
        c.sudicideAnyone();
        // top-up the (now destroyed) contract to show the effect is independent of balance
        if (amount > 0) {
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok);
        }
        // a second owner call must still not revert
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(c).balance == amount);
    }
    receive() external payable {}
}

