contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // fund C so the destruction has something to transfer
        address(c).call{value: amount}("");
        // owner destroys C
        c.sudicideAnyone();
        uint balAfterDestroy = address(c).balance;
        // a second call on the destroyed contract trivially succeeds (no code)
        bool secondReverted;
        try c.sudicideAnyone() { secondReverted = false; } catch { secondReverted = true; }
        assert(!secondReverted && balAfterDestroy == 0 && address(c).balance == 0);
    }
    receive() external payable {}
}

